package net.officefloor.hq.app.client;

import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;

/**
 * Payload to create a client, or to correct an existing client's name, email, phone number, tax number, billing address, preferred language and account manager,
 * whether their prices already include tax and whether they are tax exempt and whether they are a key account and their standard discount percentage (each left as it is when not given).
 */
public record ClientRequest(
        @NotBlank @Size(max = 255) String name,
        @NotBlank @Email(regexp = ClientRequest.EMAIL_PATTERN) @Size(max = 255) String email,
        @Size(max = 50) String phone,
        @Size(max = 50) String taxNumber,
        @Size(max = 500) String billingAddress,
        @Size(max = 50) String language,
        @Size(max = 255) String accountManager,
        Boolean taxInclusive,
        Boolean taxExempt,
        Boolean keyAccount,
        @DecimalMin("0") @DecimalMax("100") @Digits(integer = 3, fraction = 2) BigDecimal defaultDiscountPct) {

    /** Requires a dotted domain, which plain {@code @Email} does not (it accepts {@code a@b}). */
    public static final String EMAIL_PATTERN = "^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$";

    /** The phone number trimmed, or null when none was given. */
    public String trimmedPhone() {
        return phone == null || phone.isBlank() ? null : phone.trim();
    }

    /** The tax number trimmed, or null when the client is not tax registered. */
    public String trimmedTaxNumber() {
        return taxNumber == null || taxNumber.isBlank() ? null : taxNumber.trim();
    }

    /** The preferred language trimmed, or null when none was given. */
    public String trimmedLanguage() {
        return language == null || language.isBlank() ? null : language.trim();
    }

    /** The account manager trimmed, or null when none was given. */
    public String trimmedAccountManager() {
        return accountManager == null || accountManager.isBlank() ? null : accountManager.trim();
    }

    /** The billing address trimmed, or null when none was given. */
    public String trimmedBillingAddress() {
        return billingAddress == null || billingAddress.isBlank() ? null : billingAddress.trim();
    }
}
package net.officefloor.hq.app.client;

import java.math.BigDecimal;
import net.officefloor.hq.app.contact.Contact;

public record ClientResponse(Long id, String name, String email, String phone, String taxNumber, String billingAddress, String language, String accountManager, boolean taxInclusive, boolean taxExempt, boolean keyAccount, BigDecimal defaultDiscountPct, boolean archived, PrimaryContact primaryContact,
        String currency, BigDecimal creditLimit, Integer paymentTermsDays, Integer earlyPaymentWindowDays, BigDecimal outstanding) {

    /** Who the client's main contact is; null when none has been chosen. */
    public record PrimaryContact(Long id, String name) {
    }

    /** A client with what they still owe, in their currency: what is left to pay on their sent, not yet fully paid invoices. */
    public static ClientResponse from(Client client, BigDecimal outstanding) {
        Contact primary = client.getPrimaryContact();
        return new ClientResponse(client.getId(), client.getName(), client.getEmail(), client.getPhone(), client.getTaxNumber(), client.getBillingAddress(), client.getLanguage(), client.getAccountManager(), client.isTaxInclusive(), client.isTaxExempt(), client.isKeyAccount(), client.getDefaultDiscountPct(), client.isArchived(),
                primary == null ? null : new PrimaryContact(primary.getId(), primary.getName()),
                client.getCurrency(), client.getCreditLimit(), client.getPaymentTermsDays(), client.getEarlyPaymentWindowDays(), outstanding);
    }
}

    private String name;

    private String email;

    /** A number to reach the client on; none when not known. */
    private String phone;

    /** The client's tax registration number; none when they are not tax registered. */
    private String taxNumber;

    /** Where the client's bills are sent; none when not known. */
    private String billingAddress;

    /** The language the client prefers to be dealt with in; none when not known. */
    private String language;

    /** The person in the office who looks after the client; none when not recorded. */
    private String accountManager;

    private boolean archived;

    /** Whether the client's prices already include tax, so tax is worked back out of them rather than added on. */
    private boolean taxInclusive;

    /** Whether the client is tax exempt, so none of their invoices carry any tax whatever the lines say. */
    private boolean taxExempt;

    /** Whether the client is one of the office's key accounts, marked out wherever they are listed. */
    private boolean keyAccount;

    /** The client's standard discount, a percentage each new invoice for them starts with; zero when none. */
    @Column(name = "default_discount_pct", nullable = false, precision = 5, scale = 2)
    private BigDecimal defaultDiscountPct = BigDecimal.ZERO.setScale(2);

    /** The most the client may owe, in their currency; none when no limit is set. */
    @Column(precision = 12, scale = 2)
    private BigDecimal creditLimit;

    /** The number of days the client has to pay an invoice (e.g. 30 for net 30); none when no terms are agreed. */
    private Integer paymentTermsDays;

    /**
     * Part of the client's payment terms: the number of days after an invoice is issued within which paying it
     * earns its early-payment discount; within the payment terms, and none when not agreed.
     */
    private Integer earlyPaymentWindowDays;

    /** The currency the client is billed in; all of their money is in it. */
    @Column(nullable = false)
    private String currency = Currency.DEFAULT;

    /** The client's main contact, one of its own contacts; none until one is chosen. */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "primary_contact_id")
    private Contact primaryContact;

    protected Client() {
    }

    public Client(String name, String email, String phone, String taxNumber, String billingAddress) {
        this.name = name;
        this.email = email;
        this.phone = phone;
        this.taxNumber = taxNumber;
        this.billingAddress = billingAddress;
    }

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public String getEmail() {
        return email;
    }

    public String getPhone() {
        return phone;
    }

    public String getLanguage() {
        return language;
    }

    public void setLanguage(String language) {
        this.language = language;
    }

    public String getAccountManager() {
        return accountManager;
    }

    public void setAccountManager(String accountManager) {
        this.accountManager = accountManager;
    }

    public String getTaxNumber() {
        return taxNumber;
    }

    public String getBillingAddress() {
        return billingAddress;
    /** Adds a client; its email, once trimmed, must not already belong to another client. */
    @Transactional
    public ClientResponse create(ClientRequest request) {
        String email = request.email().trim();
        if (clients.existsByEmailIgnoreCase(email)) {
            throw emailTaken();
        }
        try {
            Client client = new Client(request.name().trim(), email, request.trimmedPhone(), request.trimmedTaxNumber(), request.trimmedBillingAddress());
            client.setLanguage(request.trimmedLanguage());
            client.setAccountManager(request.trimmedAccountManager());
            client.setTaxInclusive(Boolean.TRUE.equals(request.taxInclusive()));
            client.setTaxExempt(Boolean.TRUE.equals(request.taxExempt()));
            client.setKeyAccount(Boolean.TRUE.equals(request.keyAccount()));
            if (request.defaultDiscountPct() != null) {
                client.setDefaultDiscountPct(request.defaultDiscountPct());
            }
            return respond(clients.saveAndFlush(client));
        } catch (DataIntegrityViolationException e) {
            // Lost a race with a concurrent add of the same email; the unique constraint caught it.
            if (String.valueOf(e.getMessage()).toUpperCase().contains("CLIENT_EMAIL_UQ")) {
                throw emailTaken();
            }
            throw e;
        }
    }

    /**
     * Corrects a client's name, email, phone number, tax number, billing address, preferred language and account manager (each left as it is when not given, cleared when blank); the email, once trimmed, must not belong to another client.
     * When whether their prices include tax, or whether they are tax exempt, changes, their draft invoices are reworked to match; sent ones keep the
     * figures they were issued with. The change is recorded in the audit log.
     */
    @Transactional
    public ClientResponse update(Long id, ClientRequest request) {
        Client client = find(id);
        String email = request.email().trim();
        if (clients.existsByEmailIgnoreCaseAndIdNot(email, id)) {
            throw emailTaken();
        }
        client.rename(request.name().trim(), email, request.trimmedPhone(), request.trimmedTaxNumber(), request.trimmedBillingAddress());
        if (request.language() != null) {
            client.setLanguage(request.trimmedLanguage());
        }
        if (request.accountManager() != null) {
            client.setAccountManager(request.trimmedAccountManager());
        }
        if (request.taxInclusive() != null && request.taxInclusive() != client.isTaxInclusive()) {
            client.setTaxInclusive(request.taxInclusive());
            invoices.findByClientIdAndStatus(id, InvoiceStatus.DRAFT)
                    .forEach(i -> i.applyTaxInclusive(request.taxInclusive()));
        }
                    c.get("decimals") == null ? 2 : ((Number) c.get("decimals")).intValue());
