        for (Map<String, Object> r : rows(fixture, "fxRates")) {
            jdbc.update("INSERT INTO fx_rate (currency, rate_date, rate) VALUES (?, ?, ?)",
                    r.get("currency"), LocalDate.parse(r.get("date").toString()), decimal(r.get("rate")));
